from h import *
D="Договор поручения"
add([
(D,"Обеспечение (виды, требования)","Обеспечение по залогу определяется по перечню требований к залоговому обеспечению (прил. 3).","разд. «Порядок финансирования», абз. «Обеспечение по залогу»","Обеспечение по залогу определяется по перечню требовании к залоговому обеспечению согласно приложению 3 к настоящему Договору."),
(D,"Порядок финансирования/перечисления бюджетных средств","Повторное микрокредитование за счет средств, возвращенных Заемщиками по ранее выданным микрокредитам, осуществляется на условиях Договора и Правил (Приказ № 53 от 16.06.2025).","разд. «Порядок финансирования», абз. «Повторное микрокредитование»","Повторное микрокредитование претендентов за счет средств, возвращенных Заемщиками по ранее выданным микрокредитам"),
(D,"Особое условие: хранение оригиналов документов залога","Учет и хранение оригиналов правоустанавливающих и идентификационных документов на залоговое имущество осуществляет Поверенный.","разд. «Порядок финансирования», последний абзац","осуществляется Поверенным (агентом)"),
(D,"Порядок приема заявок и отбора заемщиков","Претенденты на микрокредит: граждане РК; безработные; самозанятые без регистрации ИП и бездействующие ИП; лица в неоплачиваемом семейном предпринимательстве; лица в ЛПХ с доходами ниже прожиточного минимума; кооперативы и их члены; ИП. Претенденты на лизинг — кооперативы и их члены; на переработку — ИП и кооперативы.","разд. «Основные условия займа», п. 1–2, 4","Претендентами на получение лизинга в рамках настоящих Правил являются кооперативы, а также члены кооперативов."),
(D,"Порядок приема заявок и отбора заемщиков","Претендентам без статуса ИП при одобрении необходимо зарегистрироваться в качестве ИП.","разд. «Основные условия займа», п. 3","необходимо зарегистрироваться в качестве индивидуального предпринимателя"),
(D,"Порядок приема заявок и отбора заемщиков","Для физлиц — постоянная регистрация по месту жительства не менее 12 месяцев на дату подачи заявки в сельском населенном пункте/малом городе реализации проекта; для действующих ИП и юрлиц — госрегистрация/уведомление по месту нахождения в сельском населенном пункте реализации проекта.","разд. «Основные условия займа», п. 5–6","не менее 12 (двенадцати) месяцев (на дату подачи заявки на микрокредитование)"),
(D,"Порядок приема заявок и отбора заемщиков","Кооперативы: один или несколько видов деятельности по уставу, формируются на территории одного сельского населенного пункта и/или нескольких смежных сельских округов при территориальной и логистической близости, наличии товарной массы.","разд. «Основные условия займа», п. 7","формируются на территории одного сельского населенного пункта и (или) в границах нескольких смежных сельских округов"),
(D,"Основание/программа/нормативные акты","Условия финансирования микрокредитования и лизинга предоставляются по Правилам (Приказ № 53 от 16.06.2025); общие требования устанавливаются в прил. 4.","разд. «Основные условия займа», п. 8–9","Общие требования микрокредитования и лизинга в рамках Программы устанавливаются для Претендентов в соответствии с приложением 4"),
(D,"Полномочия и обязанности поверенного","Функции Доверителя: подписание договоров микрокредита, залога и/или гарантии (прил. 5, 6, 7) и допсоглашений; учет и перечисление средств на счета Поверенного; оплата услуг и возмещение обоснованных расходов при выделении бюджетных средств (ст. 849 ГК РК); требование добросовестного исполнения; обеспечение Поверенного доверенностями для представительства в суде.","разд. «Основные функции, права и обязанности», Функции Доверителя","при условии обоснованности расходов и выделения бюджетных средств из местного бюджета в соответствии со ст. 849 Гражданского кодекса Республики Казахстан возмещает расходы"),
(D,"Полномочия и обязанности поверенного","Доверитель участвует в рассмотрении заявок, решении о предоставлении микрокредита, принятии залога/гарантий, реструктуризации и замене предмета залога — в составе Кредитной комиссии Поверенного; обеспечивает регистрацию кредитных договоров согласно п. 614 Правил исполнения бюджета и его кассового обслуживания.","разд. «Основные функции, права и обязанности», Функции Доверителя","путем участия в составе Кредитной комиссии Поверенного (агента)"),
(D,"Полномочия и обязанности поверенного","Функции Поверенного: прием пакета документов (прил. 2); оценка бизнес-проекта; подготовка договоров микрокредита/залога/гарантии (прил. 5–7); обеспечение их подписания; хранение кредитных досье и копий документов; расчеты с Заемщиками и прием платежей для направления в местный бюджет.","разд. «Основные функции, права и обязанности», Функции Поверенного","хранение кредитных досье и копии правоустанавливающих, идентификационных и иных документов Заемщика/Залогодателя"),
(D,"Отчетность и контроль","Поверенный проводит мониторинг целевого использования средств в сроки по договору микрокредита и ежемесячно предоставляет в уполномоченный орган отчет о целевом использовании микрокредитов.","разд. «Основные функции, права и обязанности», Функции Поверенного","ежемесячное предоставление в уполномоченный орган отчета о целевом использовании микрокредитов"),
(D,"Полномочия и обязанности поверенного","Досудебная работа с проблемными Заемщиками. Проблемные: просрочка более 90 календарных дней; нецелевое использование; выезд на ПМЖ за пределы РК/лишение свободы; смерть/объявление умершим с неисполнением и отказом наследников; уголовное дело о фальсификации документов; риск утраты залога; судебные тяжбы с риском потери активов; иные случаи.","разд. «Основные функции, права и обязанности», Функции Поверенного","имеющие просроченную сумму задолженности более 90 (девяносто) календарных дней"),
(D,"Полномочия и обязанности поверенного","Взыскание задолженности по законодательству и внутренним документам Поверенного; Доверитель обеспечивает доверенности. Кредитная комиссия Поверенного по письменному поручению «Заказчика» решает о судебном взыскании с Заемщиков и Гарантов, мировом/медиативном соглашении, обращении взыскания на залог.","разд. «Основные функции, права и обязанности», Функции Поверенного, последние два абзаца","принимает решение о взыскании в судебном порядке задолженности с Заемщиков и Гарантов"),
])
add([
(D,"Полномочия и обязанности поверенного","Доверитель обязуется: письменно информировать о необходимости изменений условий Договора (с проектом допсоглашения); перечислить средства по п. 1.2 и оплачивать услуги в сроки Договора; в течение 10 календарных дней с письменного запроса предоставлять доверенности для представительства в суде; своевременно предоставлять необходимые документы.","разд. «Основные функции, права и обязанности», «Доверитель обязуется»","в течение 10 (десяти) календарных дней со дня получения соответствующего письменного запроса Поверенного (агента) предоставлять доверенности"),
(D,"Полномочия и обязанности поверенного","Поверенный обязуется: взыскивать задолженность с Заемщиков/Гарантов в судебном порядке на основании доверенности и письменного поручения Доверителя; сообщать сведения о ходе исполнения по требованию.","разд. «Основные функции, права и обязанности», «Поверенный (агент) обязуется»","осуществлять взыскание задолженности с Заемщиков и/или Гарантов в судебном порядке на основании представленной доверенности и письменного поручения Доверителя"),
(D,"Возврат средств и учет","Неиспользованные средства возвращаются Доверителю в течение 3 рабочих дней после окончания периода освоения с уведомлением Доверителя.","разд. «Основные функции, права и обязанности», «Поверенный (агент) обязуется»","возвратить Доверителю неиспользованные средства в течение 3 (трех) рабочих дней после окончания периода освоения"),
(D,"Отчетность и контроль","Учет по каждому Конечному заемщику (целевое использование, освоение, погашение); информация Доверителю ежемесячно до 5 числа месяца, следующего за отчетным.","разд. «Основные функции, права и обязанности», «Поверенный (агент) обязуется»","Информацию представлять Доверителю ежемесячно в срок до 5 числа месяца, следующего за отчетным периодом"),
(D,"Отчетность и контроль","Ежеквартально до 15 числа месяца, следующего за отчетным месяцем, формирует информацию по Кредиту по форме приложения 8 к Правилам регистрации, учета и мониторинга бюджетных кредитов (приказ и.о. Министра финансов РК от 16 мая 2025 года № 236).","разд. «Основные функции, права и обязанности», «Поверенный (агент) обязуется»","Ежеквартально, в срок до 15 числа месяца, следующего за отчетным месяцем, формирует информацию по Кредиту"),
(D,"Полномочия и обязанности поверенного","Поверенный вправе: мониторить залоговое обеспечение по Технической спецификации; отступить от указаний Доверителя, если это необходимо в его интересах и запросить/получить ответ своевременно невозможно; по поручению Доверителя — обслуживание бюджетных кредитов, расчеты с заемщиками, мониторинг финансирования и финсостояния, взыскание задолженности, определение заемщиков-физлиц и заключение с ними кредитных договоров.","разд. «Основные функции, права и обязанности», «Поверенный (агент) вправе»","отступить от указаний Доверителя, если по обстоятельствам дела — это необходимо в интересах Доверителя"),
(D,"Полномочия и обязанности поверенного","Поверенный не вправе распространять персональные данные заемщиков, за исключением государственных или правовых органов, запрашиваемых официальным письмом.","разд. «Основные функции, права и обязанности», «Поверенный (агент) не вправе»","распространять персональные данные заемщиков"),
(D,"Прекращение/расторжение","Стороны вправе расторгнуть Договор по инициативе любой из Сторон либо по обоюдному волеизъявлению путем подписания Соглашения о расторжении, допсоглашений к сопутствующим соглашениям и произведением полного взаиморасчета.","разд. «Основные функции, права и обязанности», последний абзац","Стороны вправе расторгнуть Договор по инициативе любой из Сторон"),
(D,"Ответственность сторон","Поверенный не отвечает за: отказ потенциального Заемщика от кредита; неправомерность сделок Заемщика; гибель/порчу залога вследствие форс-мажора или действий Заемщика/Залогодателя; неисполнение обязательств Заемщиком/Залогодателем/Гарантом.","п. 5.1.1–5.1.4","неисполнение или ненадлежащее исполнение обязательств Заемщиком/Залогодателем/Гарантом"),
(D,"Ответственность сторон","При нецелевом использовании средств Поверенным он возвращает сумму и уплачивает штраф 0,1% от суммы нецелевого использования в течение 7 рабочих дней после обнаружения.","п. 5.2","штраф в размере 0,1% (ноль целых одна десятая) процентов от суммы нецелевого использования средств в течение 7 (семи) рабочих дней"),
(D,"Ответственность сторон","За несвоевременный возврат средств по графику погашения — пеня: не более 0,1% от суммы просроченного платежа (нарастающим итогом) за день в течение 90 дней просрочки, далее не более 0,03% за день, но не более 10% от суммы, предоставленной Доверителем, за каждый год действия Договора.","п. 5.3","не может превышать 0,03 (ноль целых трех сотых) процента от суммы просроченного платежа (с нарастающим итогом) за каждый день просрочки"),
(D,"Ответственность сторон","При несвоевременном возврате неосвоенных средств — пеня 0,1% от суммы неосвоенной части за каждый день просрочки; максимум 10% от суммы, неиспользованной Поверенным за период освоения.","п. 5.4","пеня в размере 0,1 (ноль целых одной десятой) процентов от суммы неосвоенной части средств за каждый день просрочки"),
(D,"Форс-мажор","Обстоятельства непреодолимой силы (стихийные бедствия, военные конфликты, теракты, акты госорганов и др.) сдвигают сроки по обоюдному согласию на время действия событий.","п. 6.1","сроки выполнения этих обязательств по обоюдному согласию отодвигаются на время действия этих событий"),
(D,"Форс-мажор","Отсутствие разрешений/лицензий/одобрений госорганов не является форс-мажором; Поверенный принимает меры по устранению, при невозможности инициирует расторжение. Стороны немедленно письменно извещают о начале и окончании; сторона обязана представить документ компетентного госоргана.","п. 6.2–6.4","обязана предоставить для их подтверждения документ компетентного государственного органа (организации)"),
])
add([
(D,"Срок действия","Договор вступает в силу со дня подписания и действует до полного исполнения Заемщиками обязательств по договорам микрокредита; применимо законодательство РК.","п. 7.1–7.2","Договор вступает в силу со дня его подписания Сторонами и действует до полного исполнения Заемщиками обязательств"),
(D,"Разрешение споров","Разногласия предварительно рассматриваются сторонами; не урегулированные споры разрешаются по законодательству РК (суд/подсудность не указаны).","п. 8.1–8.2","Все споры между Сторонами, по которым не было достигнуто взаимопонимание, разрешаются в соответствии с законодательством Республики Казахстан."),
(D,"Изменение условий","Условия изменяются только по взаимному согласию письменным допсоглашением.","п. 9.1","могут быть изменены только по взаимному согласию Сторон"),
(D,"Число экземпляров/язык/приоритет текста","Три экземпляра на государственном и русском языках (по одному для сторон, третий для регистрирующего органа); при разночтении приоритет у русского текста.","п. 9.2","превалирующую силу имеет текст Договора на русском языке"),
(D,"Приложения (перечень)","Договор содержит Приложения № 1–13; в файле присутствуют только приложения 2, 3, 4, 8, 9, 10; приложение 1 (график погашения), 5, 6, 7 (договоры микрокредита/залога/гарантии), 11–13 в файле отсутствуют.","п. 9.3","Настоящий Договор содержит Приложения № 1 – 13, которые являются его неотъемлемой частью."),
(D,"Реквизиты","Раздел реквизитов сторон (Доверитель: адрес, БИН, ИИК, банк; Поверенный: адрес, БИН, ИИК, БИК, Кбе) и подписи с [данные сторон].","разд. «Адреса и реквизиты сторон»","АДРЕСА И РЕКВИЗИТЫ СТОРОН"),
("Договор поручения","Разрешение споров","Подсудность/арбитраж, неустойка Доверителя за просрочку перечисления средств и оплаты услуг — отсутствуют.","—",""),
])
